332: /// Streaming zero-allocation iterator over DJI `.txt` binary flight records.
333: ///
334: /// Tracks stream byte offsets, version capabilities, and details summary partitions
335: /// to demux sequential telemetry envelopes until reaching stream boundary or EOF.
336: #[derive(Debug, Clone)]
337: pub struct RecordEnvelopeIterator<'a> {
338:     buffer: &'a [u8],
339:     current_offset: usize,
340:     end_offset: usize,
341:     capabilities: VersionCapabilities,
342:     header_offset: usize,
343:     resync: bool,
344: }
345: 
346: impl<'a> RecordEnvelopeIterator<'a> {
347:     /// Constructs a new `RecordEnvelopeIterator` from a flight log buffer and parsed header.
348:     ///
349:     /// # Stream Boundary Resolution
350:     /// - **v1–v11** (`DetailsLocation::EndOfFile`): Telemetry records reside from `header_length`
351:     ///   (100 bytes) up to `details_offset`.
352:     /// - **v12–v14** (`DetailsLocation::HeaderOffset`): Summary details reside between `header_length`
353:     ///   and `details_offset`, and telemetry records begin at `details_offset` running to EOF (`buffer.len()`).
354:     ///
355:     /// # Errors
356:     /// Returns [`FlightReaderError::CorruptedHeader`] if `details_offset` is negative.
357:     /// Returns [`FlightReaderError::UnsupportedVersion`] if header version is unhandled.
358:     pub fn new(buffer: &'a [u8], header: &TxtHeader) -> Result<Self> {
359:         let capabilities = header.capabilities()?;
360:         let header_offset = header.header_length as usize;
361: 
362:         let (current_offset, end_offset) = match capabilities.details_location {
363:             DetailsLocation::EndOfFile => {
364:                 let end = if header.details_offset >= 0 {
365:                     (header.details_offset as usize).min(buffer.len())
366:                 } else {
367:                     return Err(FlightReaderError::CorruptedHeader);
368:                 };
369:                 let start = header_offset.min(end);
370:                 (start, end)
371:             }
372:             DetailsLocation::HeaderOffset => {
373:                 let start = if header.details_offset >= 0 {
374:                     (header.details_offset as usize).min(buffer.len())
375:                 } else {
376:                     return Err(FlightReaderError::CorruptedHeader);
377:                 };
378:                 (start, buffer.len())
379:             }
380:         };
381: 
382:         Ok(Self {
383:             buffer,
384:             current_offset,
385:             end_offset,
386:             capabilities,
387:             header_offset,
388:             resync: true,
389:         })
390:     }
391: 
392:     /// Alias for [`Self::new`] for explicit naming.
393:     #[inline]
394:     pub fn from_header(buffer: &'a [u8], header: &TxtHeader) -> Result<Self> {
395:         Self::new(buffer, header)
396:     }
397: 
398:     /// Constructs an iterator over a raw record slice with known version capabilities.
399:     #[inline]
400:     pub fn from_slice(slice: &'a [u8], capabilities: VersionCapabilities) -> Self {
401:         Self {
402:             buffer: slice,
403:             current_offset: 0,
404:             end_offset: slice.len(),
405:             capabilities,
406:             header_offset: 0,
407:             resync: true,
408:         }
409:     }
410: 
411:     /// Configures whether resilient stream resynchronization is enabled.
412:     ///
413:     /// In resilient mode (`resync: true`, default), corrupted delimiters or framing errors
414:     /// advance forward byte-by-byte (`cursor += 1`) to search for the next valid record boundary
415:     /// without panicking or terminating early.
416:     #[inline]
417:     pub fn with_resync(mut self, resync: bool) -> Self {
418:         self.resync = resync;
419:         self
420:     }
421: 
422:     /// Returns whether resilient stream resynchronization is currently enabled.
423:     #[inline]
424:     pub const fn resync(&self) -> bool {
425:         self.resync
426:     }
427: 
428:     /// Current cursor offset within the input `buffer`.
429:     #[inline]
430:     pub const fn current_offset(&self) -> usize {
431:         self.current_offset
432:     }
433: 
434:     /// Synonym for [`Self::current_offset`].
435:     #[inline]
436:     pub const fn cursor(&self) -> usize {
437:         self.current_offset
438:     }
439: 
440:     /// End boundary offset bounding this record stream.
441:     #[inline]
442:     pub const fn end_offset(&self) -> usize {
443:         self.end_offset
444:     }
445: 
446:     /// Header boundary offset where records began.
447:     #[inline]
448:     pub const fn header_offset(&self) -> usize {
449:         self.header_offset
450:     }
451: 
452:     /// Version capabilities governing this record stream.
453:     #[inline]
454:     pub const fn capabilities(&self) -> &VersionCapabilities {
455:         &self.capabilities
456:     }
457: 
458:     /// Returns unconsumed slice of the record stream partition.
459:     #[inline]
460:     pub fn remaining(&self) -> &'a [u8] {
461:         if self.current_offset >= self.end_offset || self.current_offset >= self.buffer.len() {
462:             &[]
463:         } else {
464:             &self.buffer[self.current_offset..self.end_offset.min(self.buffer.len())]
465:         }
466:     }
467: }
468: 
469: impl<'a> Iterator for RecordEnvelopeIterator<'a> {
470:     type Item = Result<RawRecordEnvelope<'a>>;
471: 
472:     fn next(&mut self) -> Option<Self::Item> {
473:         let record_len_width = self.capabilities.record_len_width;
474:         let header_size = 1 + record_len_width;
475: 
476:         while self.current_offset < self.end_offset {
477:             // In resilient mode, skip stray delimiters between records
478:             if self.resync && self.buffer[self.current_offset] == RECORD_DELIMITER {
479:                 self.current_offset += 1;
480:                 continue;
481:             }
482: 
483:             // Check if remaining slice can hold at least a record header
484:             let remaining = self.end_offset - self.current_offset;
485:             if remaining < header_size {
486:                 // Trailing padding bytes before EOF or Details block
487:                 self.current_offset = self.end_offset;
488:                 return None;
489:             }
490: 
491:             let slice = &self.buffer[self.current_offset..self.end_offset];
492:             match RawRecordEnvelope::parse(slice, record_len_width) {
493:                 Ok((envelope, total_len)) => {
494:                     self.current_offset += total_len;
495:                     return Some(Ok(envelope));
496:                 }
497:                 Err(err) => {
498:                     if !self.resync {
499:                         // Strict mode: advance cursor so caller can inspect or abort
500:                         self.current_offset = match err {
501:                             FlightReaderError::InvalidRecordDelimiter { .. } => {
502:                                 self.current_offset + 1
503:                             }
504:                             _ => self.end_offset,
505:                         };
506:                         return Some(Err(err));
507:                     }
508: 
509:                     // Resilient mode: scan forward byte-by-byte (cursor += 1)
510:                     self.current_offset += 1;
511:                 }
512:             }
513:         }
514: 
515:         None
516:     }
517: }
