//! Empirical Adversarial Verification Suite: XOR De-scrambling, Zero-Allocation, and Plaintext Bypass
//!
//! Independently verifies:
//! 1. Bit-exact XOR de-scrambling across all 256 seeds and diverse record types against an independent ECMA-182 oracle.
//! 2. Zero-allocation `decode_into` correctness, scratch buffer preservation, and strict `BufferOverflow` boundary conditions.
//! 3. FeaturePoint 8 plaintext bypass (types 50 and 56) in v13 and v14 streams.
//! 4. Involutive roundtrips, sub-sized payloads, and degenerate seed behavior.

use byteorder::{ByteOrder, LittleEndian};
use flightreader_core::error::FlightReaderError;
use flightreader_core::txt::header::TxtHeader;
use flightreader_core::txt::record::{
    get_feature_point, RawRecordEnvelope, RecordEnvelopeIterator, RECORD_DELIMITER,
};
use flightreader_core::txt::version::classify_version;

// =========================================================================
// Independent Verification Oracle (ECMA-182 polynomial 0x42F0E1EBA9EA3693)
// =========================================================================

struct IndependentOracle {
    table: [u64; 256],
}

impl IndependentOracle {
    fn new() -> Self {
        let poly: u64 = 0x42F0E1EBA9EA3693;
        let mut table = [0u64; 256];
        for i in 0..256 {
            let mut crc = (i as u64) << 56;
            for _ in 0..8 {
                if (crc & (1u64 << 63)) != 0 {
                    crc = (crc << 1) ^ poly;
                } else {
                    crc <<= 1;
                }
            }
            table[i] = crc;
        }
        Self { table }
    }

    fn derive_key(&self, record_type: u8, seed: u8) -> [u8; 8] {
        let magic: u64 = 1311768467463790320; // 0x123456789ABCDEF0
        let product = magic.wrapping_mul(seed as u64);

        let mut mem = [0u8; 8];
        for i in 0..8 {
            mem[i] = ((product >> ((7 - i) * 8)) & 0xFF) as u8;
        }

        let mut crc = (record_type as u64 + seed as u64) % 256;
        for i in (0..=7).rev() {
            let idx = ((mem[i] as u64) ^ (crc & 0xFF)) as usize;
            crc = (crc >> 8) ^ self.table[idx];
        }

        crc.to_le_bytes()
    }

    fn descramble(&self, record_type: u8, scrambled_payload: &[u8]) -> Vec<u8> {
        if scrambled_payload.len() < 2 {
            return Vec::new();
        }
        let seed = scrambled_payload[0];
        let key = self.derive_key(record_type, seed);
        let ciphertext = &scrambled_payload[1..];
        let mut plaintext = Vec::with_capacity(ciphertext.len());
        for (i, &b) in ciphertext.iter().enumerate() {
            plaintext.push(b ^ key[i % 8]);
        }
        plaintext
    }
}

// =========================================================================
// 1. Bit-Exact XOR De-scrambling Tests
// =========================================================================

#[test]
fn test_exhaustive_seeds_and_record_types_against_oracle() {
    let oracle = IndependentOracle::new();

    // Test representative record types across domains:
    // 1 (OSD), 2 (Home), 3 (Gimbal), 4 (RC), 6 (Battery), 7 (CenterBattery), 8 (PushedBattery),
    // 12 (RCDebug), 13 (RecoverInfo), 14 (AppLocation), 22 (SmartBattery), 50 (Recover), 56 (KeyStorage)
    let record_types: [u8; 13] = [1, 2, 3, 4, 6, 7, 8, 12, 13, 14, 22, 50, 56];

    // Payloads with various boundary sizes:
    let test_patterns: Vec<Vec<u8>> = vec![
        vec![0xAA],                                                     // 1 byte plaintext
        vec![0x01, 0x02],                                               // 2 bytes
        vec![0x10, 0x20, 0x30, 0x40, 0x50, 0x60, 0x70],               // 7 bytes
        vec![0xDE, 0xAD, 0xBE, 0xEF, 0xCA, 0xFE, 0xBA, 0xBE],         // 8 bytes (1 block)
        vec![0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09],   // 9 bytes (1 block + 1)
        (0..53).map(|i| (i * 7) as u8).collect(),                       // 53 bytes (OSD size)
        (0..128).map(|i| (i ^ 0x55) as u8).collect(),                  // 128 bytes
    ];

    for &rt in &record_types {
        for seed in 0..=255u8 {
            let key = oracle.derive_key(rt, seed);

            for pattern in &test_patterns {
                // Scramble pattern with oracle key
                let mut wire_payload = vec![seed];
                for (i, &b) in pattern.iter().enumerate() {
                    wire_payload.push(b ^ key[i % 8]);
                }

                let env = RawRecordEnvelope::new(rt, &wire_payload);

                // Check descramble_xor
                let descrambled = env.descramble_xor().expect("descramble_xor must succeed");
                assert_eq!(
                    &descrambled, pattern,
                    "descramble_xor failed for rt={}, seed={}",
                    rt, seed
                );

                // Check decode_payload for v7, v8, v11, v12
                for version in [7, 8, 11, 12] {
                    let payload = env.decode_payload(version).expect("decode_payload must succeed");
                    assert!(payload.is_owned());
                    assert_eq!(
                        payload.as_slice(),
                        pattern.as_slice(),
                        "decode_payload failed for version={}, rt={}, seed={}",
                        version,
                        rt,
                        seed
                    );
                }

                // Check decode_into zero-allocation method
                let mut out_buf = vec![0u8; pattern.len()];
                let decoded_slice = env
                    .decode_into(8, &mut out_buf)
                    .expect("decode_into must succeed");
                assert_eq!(
                    decoded_slice,
                    pattern.as_slice(),
                    "decode_into failed for rt={}, seed={}",
                    rt,
                    seed
                );
            }
        }
    }
}

#[test]
fn test_degenerate_seeds_multiples_of_15_stress() {
    let oracle = IndependentOracle::new();
    let degenerate_seeds: [u8; 16] = [
        0, 15, 30, 45, 60, 75, 90, 105, 120, 135, 150, 165, 180, 195, 210, 225,
    ];

    let pattern = [0x42u8; 64];

    for &seed in &degenerate_seeds {
        for rt in [1u8, 2, 4, 7, 56] {
            let key = oracle.derive_key(rt, seed);
            let mut wire = vec![seed];
            for (i, &b) in pattern.iter().enumerate() {
                wire.push(b ^ key[i % 8]);
            }

            let env = RawRecordEnvelope::new(rt, &wire);
            let result = env.descramble_xor().unwrap();
            assert_eq!(result, pattern);

            let mut out = [0u8; 64];
            let res_slice = env.decode_into(8, &mut out).unwrap();
            assert_eq!(res_slice, &pattern);
        }
    }
}

// =========================================================================
// 2. Zero-Allocation `decode_into` and `BufferOverflow` Tests
// =========================================================================

#[test]
fn test_decode_into_scratch_buffer_preserves_trailing_bytes() {
    // Verify that decode_into never writes past the required slice length
    let env_plaintext = RawRecordEnvelope::new(1, &[0x11, 0x22, 0x33, 0x44]);

    let mut scratch = [0xEEu8; 16]; // sentinel 0xEE
    let decoded = env_plaintext.decode_into(1, &mut scratch).unwrap();
    assert_eq!(decoded, &[0x11, 0x22, 0x33, 0x44]);
    assert_eq!(&scratch[..4], &[0x11, 0x22, 0x33, 0x44]);
    // Trailing bytes 4..16 MUST remain 0xEE untouched
    assert!(scratch[4..].iter().all(|&b| b == 0xEE));

    // XOR version
    let key = IndependentOracle::new().derive_key(2, 42);
    let scrambled = vec![42, 0xAA ^ key[0], 0xBB ^ key[1], 0xCC ^ key[2]];
    let env_xor = RawRecordEnvelope::new(2, &scrambled);

    let mut scratch2 = [0xAAu8; 16];
    let decoded_xor = env_xor.decode_into(8, &mut scratch2).unwrap();
    assert_eq!(decoded_xor, &[0xAA, 0xBB, 0xCC]);
    assert_eq!(&scratch2[..3], &[0xAA, 0xBB, 0xCC]);
    assert!(scratch2[3..].iter().all(|&b| b == 0xAA));
}

#[test]
fn test_decode_into_buffer_overflow_exhaustive_boundary_matrix() {
    // 1. Legacy v1–v6: Plaintext (required = payload.len())
    let payload_v1 = [0x01, 0x02, 0x03, 0x04, 0x05]; // len = 5
    let env_v1 = RawRecordEnvelope::new(1, &payload_v1);

    // Capacity 0
    let mut buf0 = [0u8; 0];
    assert_eq!(
        env_v1.decode_into(3, &mut buf0).unwrap_err(),
        FlightReaderError::BufferOverflow {
            required: 5,
            capacity: 0
        }
    );

    // Capacity 4 (required - 1)
    let mut buf4 = [0u8; 4];
    assert_eq!(
        env_v1.decode_into(3, &mut buf4).unwrap_err(),
        FlightReaderError::BufferOverflow {
            required: 5,
            capacity: 4
        }
    );

    // Capacity 5 (exact match)
    let mut buf5 = [0u8; 5];
    assert_eq!(env_v1.decode_into(3, &mut buf5).unwrap(), &payload_v1);

    // Capacity 10 (excess capacity)
    let mut buf10 = [0u8; 10];
    assert_eq!(env_v1.decode_into(3, &mut buf10).unwrap(), &payload_v1);

    // 2. Scrambled v7–v12: XOR (required = payload.len() - 1)
    // Payload: [seed, c1, c2, c3, c4] -> len = 5, required plaintext len = 4
    let key = IndependentOracle::new().derive_key(1, 100);
    let payload_v7 = [100, 1 ^ key[0], 2 ^ key[1], 3 ^ key[2], 4 ^ key[3]];
    let env_v7 = RawRecordEnvelope::new(1, &payload_v7);

    // Capacity 0
    let mut buf_xor0 = [0u8; 0];
    assert_eq!(
        env_v7.decode_into(8, &mut buf_xor0).unwrap_err(),
        FlightReaderError::BufferOverflow {
            required: 4,
            capacity: 0
        }
    );

    // Capacity 3 (required - 1)
    let mut buf_xor3 = [0u8; 3];
    assert_eq!(
        env_v7.decode_into(8, &mut buf_xor3).unwrap_err(),
        FlightReaderError::BufferOverflow {
            required: 4,
            capacity: 3
        }
    );

    // Capacity 4 (exact match)
    let mut buf_xor4 = [0u8; 4];
    assert_eq!(
        env_v7.decode_into(8, &mut buf_xor4).unwrap(),
        &[1, 2, 3, 4]
    );

    // Capacity 8 (excess capacity)
    let mut buf_xor8 = [0u8; 8];
    assert_eq!(
        env_v7.decode_into(8, &mut buf_xor8).unwrap(),
        &[1, 2, 3, 4]
    );

    // 3. Modern v13–v14: Raw Envelope / Plaintext Bypass (required = payload.len())
    let payload_v13 = [0x5A; 16];
    let env_v13 = RawRecordEnvelope::new(56, &payload_v13);

    let mut buf_v13_15 = [0u8; 15]; // required - 1
    assert_eq!(
        env_v13.decode_into(13, &mut buf_v13_15).unwrap_err(),
        FlightReaderError::BufferOverflow {
            required: 16,
            capacity: 15
        }
    );

    let mut buf_v13_16 = [0u8; 16]; // exact
    assert_eq!(
        env_v13.decode_into(13, &mut buf_v13_16).unwrap(),
        &payload_v13
    );

    let mut buf_v13_32 = [0u8; 32]; // excess
    assert_eq!(
        env_v13.decode_into(13, &mut buf_v13_32).unwrap(),
        &payload_v13
    );
}

#[test]
fn test_decode_into_sub_sized_and_empty_payloads() {
    // 1. Empty payload in XOR version: returns Ok(&[])
    let env_empty = RawRecordEnvelope::new(1, &[]);
    let mut buf = [0u8; 8];
    assert_eq!(env_empty.decode_into(8, &mut buf).unwrap(), &[]);

    // 2. Length 1 payload (seed only): returns PayloadTooShort
    let env_seed_only = RawRecordEnvelope::new(1, &[42]);
    assert_eq!(
        env_seed_only.decode_into(8, &mut buf).unwrap_err(),
        FlightReaderError::PayloadTooShort {
            minimum: 2,
            available: 1
        }
    );

    // 3. Length 2 payload (seed + 1 byte): exact minimal valid XOR payload
    let key = IndependentOracle::new().derive_key(1, 42);
    let env_min_valid = RawRecordEnvelope::new(1, &[42, 0x77 ^ key[0]]);
    let mut min_buf = [0u8; 1];
    assert_eq!(env_min_valid.decode_into(8, &mut min_buf).unwrap(), &[0x77]);
}

// =========================================================================
// 3. FeaturePoint 8 Plaintext Bypass (Types 50 and 56) in v13 and v14
// =========================================================================

#[test]
fn test_feature_point_8_plaintext_bypass_mapping_and_behavior() {
    for version in [13u8, 14] {
        // 1. Type 56 (KeyStorage) MUST be FeaturePoint 8
        assert_eq!(
            get_feature_point(version, 56),
            8,
            "KeyStorage (56) must map to FeaturePoint 8 in v{}",
            version
        );

        // 2. Type 50 (FlightRecordRecover) MUST be FeaturePoint 8
        assert_eq!(
            get_feature_point(version, 50),
            8,
            "FlightRecordRecover (50) must map to FeaturePoint 8 in v{}",
            version
        );

        // 3. Wire payload for KeyStorage (56)
        let key_storage_bytes = [
            0x01, // FeaturePoint 1
            0x00, 0x00, 0x00, // Reserved subheader
            0x10, 0x20, 0x30, 0x40, 0x50, 0x60, 0x70, 0x80, // AES ciphertext token
            0x90, 0xA0, 0xB0, 0xC0, 0xD0, 0xE0, 0xF0, 0xFF,
        ];
        let env_ks = RawRecordEnvelope::new(56, &key_storage_bytes);
        assert!(env_ks.is_plaintext_bypass());

        // decode_payload returns borrowed slice without decryption or allocation
        let p_ks = env_ks.decode_payload(version).unwrap();
        assert!(p_ks.is_borrowed());
        assert_eq!(p_ks.as_slice(), &key_storage_bytes);

        // decode_into writes directly to destination buffer
        let mut out_ks = [0u8; 20];
        let decoded_ks = env_ks.decode_into(version, &mut out_ks).unwrap();
        assert_eq!(decoded_ks, &key_storage_bytes);

        // 4. Wire payload for FlightRecordRecover (50)
        let recover_bytes = [0x52, 0x45, 0x43, 0x4F, 0x56, 0x45, 0x52, 0x31]; // "RECOVER1"
        let env_rec = RawRecordEnvelope::new(50, &recover_bytes);
        assert!(env_rec.is_plaintext_bypass());

        let p_rec = env_rec.decode_payload(version).unwrap();
        assert!(p_rec.is_borrowed());
        assert_eq!(p_rec.as_slice(), &recover_bytes);

        let mut out_rec = [0u8; 8];
        let decoded_rec = env_rec.decode_into(version, &mut out_rec).unwrap();
        assert_eq!(decoded_rec, &recover_bytes);

        // 5. Contrast with regular encrypted types: OSD (1), Home (2), Gimbal (3), RC (4)
        for &encrypted_type in &[1u8, 2, 3, 4] {
            let env_enc = RawRecordEnvelope::new(encrypted_type, &[0xAA; 16]);
            assert!(
                !env_enc.is_plaintext_bypass(),
                "Type {} should NOT be flagged as plaintext bypass",
                encrypted_type
            );
            assert_ne!(
                get_feature_point(version, encrypted_type),
                8,
                "Type {} should NOT map to FeaturePoint 8 in v{}",
                encrypted_type,
                version
            );
        }
    }
}

#[test]
fn test_v14_extended_feature_point_8_bypass_types() {
    // In v14, types 50, 55, 56, 209, 218, 226 are mapped to FeaturePoint 8 per SPECS.md §4.2
    for &bypass_type in &[50u8, 55, 56, 209, 218, 226] {
        assert_eq!(
            get_feature_point(14, bypass_type),
            8,
            "v14 type {} must map to FeaturePoint 8",
            bypass_type
        );
    }
}

// =========================================================================
// 4. Synthetic Stream Demuxing with Mixed Bypass & Encrypted Records
// =========================================================================

#[test]
fn test_synthetic_v13_v14_mixed_stream_demuxing() {
    for version in [13u8, 14] {
        // Header: details at 100..120, records at 120..
        let mut file_buf = vec![0u8; 100];
        LittleEndian::write_i64(&mut file_buf[0..8], 120);
        LittleEndian::write_i16(&mut file_buf[8..10], 100);
        file_buf[10] = version;
        file_buf[11] = 3; // DJIFly
        file_buf[12] = 1; // Scrambled

        // 20 bytes details block
        file_buf.extend_from_slice(&[0x33; 20]);

        // Sequence of records:
        // 1. KeyStorage (56) - bypass
        let ks_payload = [0x11u8; 16];
        file_buf.push(56);
        file_buf.extend_from_slice(&(ks_payload.len() as u16).to_le_bytes());
        file_buf.extend_from_slice(&ks_payload);
        file_buf.push(RECORD_DELIMITER);

        // 2. OSD (1) - encrypted
        let osd_payload = [0x22u8; 32];
        file_buf.push(1);
        file_buf.extend_from_slice(&(osd_payload.len() as u16).to_le_bytes());
        file_buf.extend_from_slice(&osd_payload);
        file_buf.push(RECORD_DELIMITER);

        // 3. FlightRecordRecover (50) - bypass
        let rec_payload = [0x33u8; 8];
        file_buf.push(50);
        file_buf.extend_from_slice(&(rec_payload.len() as u16).to_le_bytes());
        file_buf.extend_from_slice(&rec_payload);
        file_buf.push(RECORD_DELIMITER);

        // 4. Gimbal (3) - encrypted
        let gimbal_payload = [0x44u8; 16];
        file_buf.push(3);
        file_buf.extend_from_slice(&(gimbal_payload.len() as u16).to_le_bytes());
        file_buf.extend_from_slice(&gimbal_payload);
        file_buf.push(RECORD_DELIMITER);

        let header = TxtHeader::parse(&file_buf).unwrap();
        let mut iter = RecordEnvelopeIterator::new(&file_buf, &header).unwrap();
        assert_eq!(iter.current_offset(), 120);

        // Rec 1: KeyStorage
        let r1 = iter.next().unwrap().unwrap();
        assert_eq!(r1.record_type, 56);
        assert!(r1.is_plaintext_bypass());
        assert_eq!(r1.payload, &ks_payload);

        // Rec 2: OSD
        let r2 = iter.next().unwrap().unwrap();
        assert_eq!(r2.record_type, 1);
        assert!(!r2.is_plaintext_bypass());
        assert_eq!(r2.payload, &osd_payload);

        // Rec 3: FlightRecordRecover
        let r3 = iter.next().unwrap().unwrap();
        assert_eq!(r3.record_type, 50);
        assert!(r3.is_plaintext_bypass());
        assert_eq!(r3.payload, &rec_payload);

        // Rec 4: Gimbal
        let r4 = iter.next().unwrap().unwrap();
        assert_eq!(r4.record_type, 3);
        assert!(!r4.is_plaintext_bypass());
        assert_eq!(r4.payload, &gimbal_payload);

        assert!(iter.next().is_none());
    }
}

